module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic done_counting,
    input  logic ack,
    output logic shift_ena,
    output logic counting,
    output logic done
);

    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_1     = 3'd1,
        S_11    = 3'd2,
        S_110   = 3'd3,
        S_SHIFT = 3'd4,
        S_COUNT = 3'd5,
        S_DONE  = 3'd6
    } state_t;

    state_t current_state, next_state;
    logic [1:0] shift_cnt;

    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= S_IDLE;
            shift_cnt     <= 2'd0;
        end else begin
            current_state <= next_state;
            if (current_state == S_SHIFT) begin
                shift_cnt <= shift_cnt + 2'd1;
            end else begin
                shift_cnt <= 2'd0;
            end
        end
    end

    always_comb begin
        next_state = current_state;
        case (current_state)
            S_IDLE: begin
                if (data) next_state = S_1;
                else next_state = S_IDLE;
            end
            S_1: begin
                if (data) next_state = S_11;
                else next_state = S_IDLE;
            end
            S_11: begin
                if (data) next_state = S_11;
                else next_state = S_110;
            end
            S_110: begin
                if (data) next_state = S_SHIFT;
                else next_state = S_IDLE;
            end
            S_SHIFT: begin
                if (shift_cnt == 2'd3) next_state = S_COUNT;
                else next_state = S_SHIFT;
            end
            S_COUNT: begin
                if (done_counting) next_state = S_DONE;
                else next_state = S_COUNT;
            end
            S_DONE: begin
                if (ack) next_state = S_IDLE;
                else next_state = S_DONE;
            end
            default: next_state = S_IDLE;
        endcase
    end

    assign shift_ena = (current_state == S_SHIFT);
    assign counting  = (current_state == S_COUNT);
    assign done      = (current_state == S_DONE);

endmodule

